#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/wait.h>
#include <unistd.h>

static int global_var = 1;

static void *thread_func(void *arg) {
    (void)arg;
    global_var = 200;
    printf("thread: global_var=%d, pid=%ld\n", global_var, (long)getpid());
    return NULL;
}

int main(void) {
    printf("parent before fork: global_var=%d, pid=%ld\n", global_var, (long)getpid());
    fflush(stdout);

    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return 1;
    }

    if (pid == 0) {
        global_var = 100;
        printf("child process: global_var=%d, pid=%ld\n", global_var, (long)getpid());
        fflush(stdout);
        _exit(0);
    }

    int status = 0;
    if (waitpid(pid, &status, 0) < 0) {
        perror("waitpid");
        return 1;
    }
    printf("parent after child exit: global_var=%d\n", global_var);

    pthread_t tid;
    if (pthread_create(&tid, NULL, thread_func, NULL) != 0) {
        perror("pthread_create");
        return 1;
    }
    pthread_join(tid, NULL);
    printf("main thread after join: global_var=%d\n", global_var);

    return WIFEXITED(status) && global_var == 200 ? 0 : 1;
}
